func _process(delta: float) -> void:
	if _tail_left >= 0.0:
		_tail_left -= delta
		if _tail_left <= 0.0:
			queue_free()
		return
	if _scarecrow == null:
		return
	_set_ratio(clampf(_scarecrow.burn_time_left / Tuning.BURN_DURATION, 0.0, 1.0))


func _on_burning_started() -> void:
	_set_ratio(1.0)
	_set_emitting(true)

force = gravity;
// Apply linear acceleration.
force += length(USERDATA1.xyz) > 0.0 ? normalize(USERDATA1.xyz) * physics_params.linear_accel : vec3(0.0);
// Apply radial acceleration.
vec3 org = EMISSION_TRANSFORM[3].xyz;
vec3 diff = pos - org;
force += length(diff) > 0.0 ? normalize(diff) * physics_params.radial_accel : vec3(0.0);
// Apply tangential acceleration.
float tangent_accel_val = physics_params.tangent_accel;
force += length(diff.yx) > 0.0 ? vec3(normalize(diff.yx * vec2(-1.0, 1.0)), 0.0) * tangent_accel_val : vec3(0.0);
force += ATTRACTOR_FORCE;
force.z = 0.0;
// Apply attractor forces.
USERDATA1.xyz += force * DELTA;
